struct Inner<E: Endpoint, C: Callbacks, T: tun::Writer, B: udp::Writer<E>> {
    ready: AtomicBool,                       // job status
    buffer: Mutex<(Option<E>, Vec<u8>)>,     // endpoint & ciphertext buffer
